CodeAssembler& CodeAssemblerFns0::enter(std::int32_t op0, std::int32_t op1) {
	Code code;
	if (bitness() == 64) {
		code = Code::Enterq_imm16_imm8;
	} else if (bitness() >= 32) {
		code = Code::Enterd_imm16_imm8;
	} else {
		code = Code::Enterw_imm16_imm8;
	}
	return add_instr(Instruction::with2(code, op0, op1));
}

